import React, { useState, useEffect, useRef } from 'react';
import {
    Calendar,
    MapPin,
    Clock,
    Heart,
    ChevronDown,
    Music,
    Music2,
    Upload,
    Phone,
    Home,
    MailOpen
} from 'lucide-react';

function App() {
    const [activeTab, setActiveTab] = useState('home');
    const [isPlaying, setIsPlaying] = useState(false);
    const [isVisible, setIsVisible] = useState(true);
    const audioRef = useRef(null);

    const weddingDate = "September 8, 2024";
    const weddingTime = "12:30 PM";
    const locationAddress = "178/03, Welipitiya Road, Koledanda, Weligama, 81700";
    const contactNumber = "+94 77 148 3381";
    const googleDriveLink = "https://drive.google.com"; // replace with your folder

    // Control fade animation on tab change
    useEffect(() => {
        setIsVisible(false);
        const timer = setTimeout(() => setIsVisible(true), 100);
        return () => clearTimeout(timer);
    }, [activeTab]);

    // Play/pause background music
    useEffect(() => {
        if (audioRef.current) {
            if (isPlaying) audioRef.current.play();
            else audioRef.current.pause();
        }
    }, [isPlaying]);

    const TabButton = ({ id, label, icon: Icon }) => (
        <button
            onClick={() => setActiveTab(id)}
            className={`flex items-center space-x-2 px-4 py-2 rounded-full transition-all duration-300 ${
                activeTab === id
                    ? 'bg-[#D4AF37] text-white'
                    : 'text-[#4A4238] hover:bg-[#D4AF37]/10'
            }`}
        >
            <Icon size={16} />
            <span className="text-xs uppercase tracking-widest font-bold">{label}</span>
        </button>
    );

    return (
        <div className="min-h-screen bg-[#FFFBF5] text-[#4A4238] font-serif relative">

            {/* Audio */}
            <audio ref={audioRef} src="/audio/fathiha.mp3" loop />

            {/* NAVBAR */}
            <nav className="fixed top-0 w-full z-50 bg-white/70 backdrop-blur border-b border-[#D4AF37]/20 px-6 py-4">
                <div className="max-w-6xl mx-auto flex justify-between items-center">
                    <h2 className="text-xl italic">
                        Shazeen <span className="text-[#D4AF37]">&</span> Shimra
                    </h2>
                    <div className="hidden md:flex space-x-2">
                        <TabButton id="home" label="Home" icon={Home} />
                        <TabButton id="invitation" label="Invitation" icon={MailOpen} />
                        <TabButton id="location" label="Location" icon={MapPin} />
                    </div>
                </div>
            </nav>

            {/* MAIN CONTENT */}
            <main className={`pt-28 px-6 transition-all duration-700 ${isVisible ? 'opacity-100' : 'opacity-0'}`}>

                {/* HOME */}
                {activeTab === 'home' && (
                    <section className="min-h-[80vh] flex flex-col items-center justify-center text-center space-y-8">
            <span className="border-y border-[#D4AF37] px-4 py-1 text-[#D4AF37] text-xs tracking-[0.4em] uppercase">
              Together with their families
            </span>

                        <h1 className="text-6xl md:text-9xl font-light italic">
                            Shazeen
                            <span className="text-[#D4AF37] mx-4">&</span>
                            Shimra
                        </h1>

                        <p className="italic opacity-70 text-xl">
                            Cordially invite you to celebrate their
                            <span className="block text-3xl mt-2 not-italic">
                Fathiha Ceremony
              </span>
                        </p>

                        <div className="mt-8">
                            <p className="text-5xl text-[#D4AF37]">{weddingDate}</p>
                            <p className="uppercase text-xs tracking-widest mt-2">
                                At Our Residence
                            </p>
                        </div>

                        <button
                            onClick={() => setActiveTab('invitation')}
                            className="flex flex-col items-center text-[#D4AF37] mt-6"
                        >
                            <span className="text-xs uppercase tracking-widest font-bold">More Details</span>
                            <ChevronDown className="animate-bounce mt-2" />
                        </button>
                    </section>
                )}

                {/* INVITATION */}
                {activeTab === 'invitation' && (
                    <section className="max-w-4xl mx-auto bg-white/50 rounded-3xl p-10 shadow-xl space-y-10 text-center">
                        <Heart className="mx-auto text-[#D4AF37]" size={48} />

                        <h2 className="text-5xl italic font-light">The Invitation</h2>

                        <p className="text-lg opacity-80">
                            We warmly invite you to join us as we begin our journey together.
                            Your presence, prayers, and blessings mean everything to us.
                        </p>

                        <div className="grid md:grid-cols-3 gap-8 border-y py-8">
                            <div>
                                <MapPin className="mx-auto text-[#D4AF37]" />
                                <p className="uppercase text-xs mt-2 tracking-widest">Location</p>
                                <p>Our Residence</p>
                            </div>
                            <div>
                                <Calendar className="mx-auto text-[#D4AF37]" />
                                <p className="uppercase text-xs mt-2 tracking-widest">Date</p>
                                <p>8th September 2024</p>
                            </div>
                            <div>
                                <Clock className="mx-auto text-[#D4AF37]" />
                                <p className="uppercase text-xs mt-2 tracking-widest">Time</p>
                                <p>{weddingTime}</p>
                            </div>
                        </div>

                        <a
                            href={googleDriveLink}
                            target="_blank"
                            rel="noreferrer"
                            className="inline-flex items-center px-8 py-4 bg-[#D4AF37] text-white rounded-full uppercase tracking-widest text-xs font-bold"
                        >
                            <Upload className="mr-2" />
                            Upload Memories
                        </a>
                    </section>
                )}

                {/* LOCATION */}
                {activeTab === 'location' && (
                    <section className="max-w-4xl mx-auto space-y-10">
                        <h2 className="text-5xl italic text-center">Find Your Way</h2>

                        <div className="bg-white/50 rounded-3xl p-8 shadow-lg space-y-6 text-center">
                            <p className="text-xl">{locationAddress}</p>
                            <a
                                href={`tel:${contactNumber}`}
                                className="flex justify-center items-center text-[#D4AF37] mt-2"
                            >
                                <Phone className="mr-2" />
                                {contactNumber}
                            </a>
                        </div>
                    </section>
                )}

            </main>

            {/* MUSIC BUTTON */}
            <button
                onClick={() => setIsPlaying(!isPlaying)}
                className="fixed bottom-6 right-6 w-16 h-16 bg-white/90 rounded-full shadow-2xl flex items-center justify-center text-[#D4AF37]"
            >
                {isPlaying ? <Music2 className="animate-pulse" /> : <Music />}
                <div className="absolute -top-1 -right-1 w-5 h-5 bg-[#D4AF37] rounded-full flex items-center justify-center text-[8px] text-white font-bold">
                    {isPlaying ? 'OFF' : 'ON'}
                </div>
            </button>

            {/* FOOTER */}
            <footer className="py-6 text-center text-xs tracking-widest opacity-40">
                Designed with Elegance for Shazeen & Shimra
            </footer>
        </div>
    );
}

export default App;
